ap;overflow:hidden;text-overflow:ellipsis}\n.wx-wi{flex:none;width:14px;height:14px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}\n.wx-today{font-size:12px;color:var(--muted);white-space:nowrap}\n\n.i-sun circle{fill:var(--accent)}\n.i-sun line{stroke:var(--accent);stroke-width:2.6;stroke-linecap:round}\n.i-cloud{fill:var(--muted);fill:color-mix(in srgb,var(--muted) 70%,var(--paper))}\n.i-drop{fill:none;stroke:var(--accent-alt);stroke-width:2.6;stroke-linecap:round}\n.i-flake{fill:var(--accent-alt)}\n.i-bolt{fill:var(--accent)}\n.i-fog{fill:none;stroke:var(--muted);stroke-width:3;stroke-linecap:round}\n.i-none{fill:none;stroke:var(--muted);stroke-width:2.4;stroke-dasharray:4 4}\n\n.wx-foot{flex:none;display:grid;gap:1px;min-width:0;padding-top:6px;border-top:1px solid var(--line);font-size:11px;line-height:1.35;color:var(--muted)}\n.wx-foot>div{min-width:0;overflow-wrap:anywhere}\n.wx-upd{color:var(--ink)}\n.wx-st.is-bad{color:var(--ink);font-weight:600}\n.wx-reason{font-weight:400;color:var(--muted)}\n\n.wx-empty{display:grid;gap:5px;justify-items:start;padding:8px 10px;border:1px solid var(--line);border-left:3px solid var(--accent);border-radius:8px;background:var(--soft)}\n.wx-empty-t{font-size:14px;font-weight:700}\n.wx-empty-d{font-size:12px;color:var(--muted);overflow-wrap:anywhere}\n.wx-btn{margin-top:2px;padding:5px 14px;border:0;border-radius:8px;background:var(--accent);color:var(--on-accent);font-weight:600;cursor:pointer}\n.wx-skel{display:grid;gap:8px;padding-top:4px}\n.wx-bar{height:26px;border-radius:8px;background:var(--soft);animation:wx-pulse 1.4s ease-in-out infinite}\n.wx-bar.short{width:60%;height:16px}\n.wx-skel-t{font-size:12px;color:var(--muted)}\n@keyframes wx-pulse{50%{opacity:.45}}\n.wx-note{grid-column:1/-1;font-size:12px;color:var(--muted)}\n.wx-days{display:none}\n\n.card[data-size=\"6x3\"] .wx-days,.card[data-size=\"3x6\"] .wx-days,.card[data-size=\"6x6\"] .wx-days{display:grid;min-width:0}\n.wx-day{min-width:0;display:grid;justify-items:center;align-content:center;text-align:center;gap:3px;padding:8px 4px;border:1px solid var(--line);border-radius:10px;background:var(--soft);grid-template-areas:\"l\" \"i\" \"w\" \"t\"}\n.wx-dl{grid-area:l;display:flex;flex-direction:column;align-items:center;line-height:1.2}\n.wx-dl b{font-size:13px}\n.wx-dl span{font-size:11px;color:var(--muted)}\n.wx-di{grid-area:i;width:26px;height:26px}\n.wx-di svg{display:block;width:100%;height:100%}\n.wx-dw{grid-area:w;max-width:100%;font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.wx-dt{grid-area:t;max-width:100%;font-size:12px;font-weight:700;white-space:nowrap;font-variant-numeric:tabular-nums}\n\n.card[data-size=\"6x3\"] .wx-body{grid-template-columns:minmax(0,1fr) minmax(0,2fr);gap:10px;align-content:stretch}\n.card[data-size=\"6x3\"] .wx-now{align-content:center}\n.card[data-size=\"6x3\"] .wx-days{grid-template-columns:repeat(3,minmax(0,1fr));gap:6px}\n.card[data-size=\"6x3\"] .wx-dl span{display:none}\n.card[data-size=\"6x3\"] .wx-days.is-empty{display:grid;align-content:center}\n.card[data-size=\"6x3\"] .wx-empty{grid-column:1/-1}\n\n.card[data-size=\"3x6\"] .wx{gap:8px}\n.card[data-size=\"3x6\"] .wx-icon{width:44px;height:44px}\n.card[data-size=\"3x6\"] .wx-temp{font-size:42px}\n.card[data-size=\"3x6\"] .wx-days{gap:6px}\n.card[data-size=\"3x6\"] .wx-day{grid-template-columns:28px minmax(0,1fr) auto;grid-template-areas:\"i l t\" \"i w w\";justify-items:stretch;text-align:left;column-gap:8px;row-gap:1px;padding:6px 8px}\n.card[data-size=\"3x6\"] .wx-dl{flex-direction:row;align-items:baseline;gap:6px}\n.card[data-size=\"3x6\"] .wx-di{width:28px;height:28px;align-self:center}\n.card[data-size=\"3x6\"] .wx-dt{justify-self:end}\n\n.card[data-size=\"6x6\"] .wx{padding:16px;gap:10px}\n.card[data-size=\"6x6\"] .wx-city{font-size:16px}\n.card[data-size=\"6x6\"] .wx-body{gap:16px}\n.card[data-size=\"6x6\"] .wx-now{grid-template-columns:auto auto minmax(0,1fr);grid-template-areas:\"icon temp meta\";column-gap:14px}\n.card[data-size=\"6x6\"] .wx-icon{width:72px;height:72px}\n.card[data-size=\"6x6\"] .wx-temp{font-size:64px}\n.card[data-size=\"6x6\"] .wx-cond{font-size:18px}\n.card[data-size=\"6x6\"] .wx-wind,.card[data-size=\"6x6\"] .wx-today{font-size:13px}\n.card[data-size=\"6x6\"] .wx-meta{gap:4px}\n.card[data-size=\"6x6\"] .wx-days{grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}\n.card[data-size=\"6x6\"] .wx-day{gap:6px;padding:16px 6px}\n.card[data-size=\"6x6\"] .wx-dl b{font-size:15px}\n.card[data-size=\"6x6\"] .wx-dl span{font-size:12px}\n.card[data-size=\"6x6\"] .wx-di{width:44px;height:44px}\n.card[data-size=\"6x6\"] .wx-dw{font-size:13px}\n.card[data-size=\"6x6\"] .wx-dt{font-size:15px}\n.card[data-size=\"6x6\"] .wx-foot{font-size:12px}\n\n.card[data-size=\"3x3\"] .wx-reason{display:none}\n";
const SVGNS='http://www.w3.org/2000/svg';
function sv(tag,attrs,kids){
  const n=document.createElementNS(SVGNS,tag);
  Object.keys(attrs||{}).forEach(function(k){n.setAttribute(k,String(attrs[k]));});
  (kids||[]).forEach(function(c){if(c)n.appendChild(c);});
  return n;
}
function cloudG(tx,ty,sc){
  return sv('g',{class:'i-cloud',transform:'translate('+tx+' '+ty+') scale('+sc+')'},[
    sv('circle',{cx:17,cy:31,r:6}),sv('circle',{cx:26,cy:25,r:9}),
    sv('circle',{cx:35,cy:31,r:6}),sv('rect',{x:17,y:31,width:18,height:6})
  ]);
}
function sunG(cx,cy,r,r0,r1){
  const k=[sv('circle',{cx:cx,cy:cy,r:r})];
  for(let i=0;i<8;i++){
    const a=i*Math.PI/4,c=Math.cos(a),s=Math.sin(a);
    k.push(sv('line',{x1:(cx+c*r0).toFixed(1),y1:(cy+s*r0).toFixed(1),x2:(cx+c*r1).toFixed(1),y2:(cy+s*r1).toFixed(1)}));
  }
  return sv('g',{class:'i-sun'},k);
}
function kindOf(text){
  const t=String(text==null?'':text);
  if(!t)return 'none';
  if(/雷/.test(t))return 'thunder';
  if(/雪|冰雹|冻雨/.test(t))return 'snow';
  if(/雨/.test(t))return 'rain';
  if(/雾|霾|沙|尘/.test(t))return 'fog';
  if(/多云|少云/.test(t))return 'partly';
  if(/阴/.test(t))return 'cloud';
  if(/晴/.test(t))return 'sun';
  return 'none';
}
function wxIcon(kind){
  const s=sv('svg',{viewBox:'0 0 48 48',class:'wx-ico','aria-hidden':'true',focusable:'false'},[]);
  const add=function(n){s.appendChild(n);};
  if(kind==='sun'){add(sunG(24,24,8,12,18));}
  else if(kind==='partly'){add(sunG(17,17,6,9,13));add(cloudG(3,5,0.95));}
  else if(kind==='cloud'){add(cloudG(-2,-1,1));}
  else if(kind==='rain'){
    add(cloudG(0,-4,1));
    [17,25,33].forEach(function(x){add(sv('path',{class:'i-drop',d:'M'+x+' 36l-2 7'}));});
  }
  else if(kind==='snow'){
    add(cloudG(0,-4,1));
    [[17,38],[25,42],[33,38]].forEach(function(p){add(sv('circle',{class:'i-flake',cx:p[0],cy:p[1],r:2}));});
  }
  else if(kind==='thunder'){
    add(cloudG(0,-6,1));
    add(sv('polygon',{class:'i-bolt',points:'27,30 19,40 24,40 21,47'}));
  }
  else if(kind==='fog'){
    add(sv('path',{class:'i-fog',d:'M12 17h24M9 25h30M14 33h22'}));
  }
  else{add(sv('circle',{class:'i-none',cx:24,cy:24,r:12}));}
  return s;
}
function windIcon(){
  return sv('svg',{viewBox:'0 0 24 24',class:'wx-wi','aria-hidden':'true',focusable:'false'},[
    sv('path',{d:'M3 9h11a3 3 0 1 0-3-3'}),sv('path',{d:'M3 15h15a3 3 0 1 1-3 3'})
  ]);
}
function refreshIcon(){
  return sv('svg',{viewBox:'0 0 24 24','aria-hidden':'true',focusable:'false'},[
    sv('path',{d:'M20 12a8 8 0 1 1-2.34-5.66'}),sv('path',{d:'M20 4v5h-5'})
  ]);
}

function p2(n){return String(n).length<2?'0'+n:String(n);}
function fmtT(v){
  if(v==null||v==='')return '—';
  const n=Number(v);
  return isFinite(n)?String(n)+'°':String(v);
}
function fmtWind(dir,pow){
  const parts=[];
  if(dir!=null&&String(dir).trim()){
    const d=String(dir).trim();
    parts.push(d.indexOf('风')>=0?d:d+'风');
  }
  if(pow!=null&&String(pow).trim()){
    const p=String(pow).trim();
    parts.push(/^\d+(\.\d+)?$/.test(p)?p+'级':p);
  }
  return parts.length?parts.join(' '):'风况未提供';
}
function fmtLocal(d){
  return p2(d.getMonth()+1)+'-'+p2(d.getDate())+' '+p2(d.getHours())+':'+p2(d.getMinutes());
}
function fmtReport(v){
  if(v==null||v==='')return '';
  const s=String(v).trim();
  if(/^\d{13}$/.test(s)||/^\d{10}$/.test(s)){
    const d=new Date(s.length===10?Number(s)*1000:Number(s));
    return isNaN(d.getTime())?'':fmtLocal(d);
  }
  if(/\d{2}:\d{2}.*(Z|[+-]\d{2}:?\d{2})$/.test(s)){
    const d=new Date(s);
    if(!isNaN(d.getTime()))return fmtLocal(d);
  }
  const m=s.match(/(\d{4})[-\/.](\d{1,2})[-\/.](\d{1,2})[ T]+(\d{1,2}):(\d{2})/);
  if(m)return p2(m[2])+'-'+p2(m[3])+' '+p2(m[4])+':'+m[5];
  return s.length>20?s.slice(0,20):s;
}
function fmtAt(ms,today){
  const d=new Date(ms);
  if(isNaN(d.getTime()))return '';
  const hm=p2(d.getHours())+':'+p2(d.getMinutes());
  const ymd=d.getFullYear()+'-'+p2(d.getMonth()+1)+'-'+p2(d.getDate());
  return ymd===today?hm:p2(d.getMonth()+1)+'-'+p2(d.getDate())+' '+hm;
}
function parseD(s){
  const m=String(s==null?'':s).match(/(\d{4})-(\d{1,2})-(\d{1,2})/);
  return m?new Date(Number(m[1]),Number(m[2])-1,Number(m[3])):null;
}
function dayDiff(s,today){
  const a=parseD(s),b=parseD(today);
  if(!a||!b)return null;
  return Math.round((a.getTime()-b.getTime())/86400000);
}
function dayLabel(s,diff){
  const a=parseD(s);
  if(!a)return {main:String(s||'—'),sub:''};
  const main=diff===1?'明天':diff===2?'后天':'周'+'日一二三四五六'.charAt(a.getDay());
  return {main:main,sub:(a.getMonth()+1)+'/'+a.getDate()};
}
function listDays(fc,today){
  const list=fc.filter(function(f){return f&&typeof f==='object';});
  const dated=list.map(function(f){return {f:f,diff:dayDiff(f.date,today)};}).filter(function(x){return x.diff!==null;});
  if(!dated.length)return {fut:list.slice(0,3).map(function(f){return {f:f,diff:null};}),now:null};
  dated.sort(function(a,b){return a.diff-b.diff;});
  const cur=dated.filter(function(x){return x.diff===0;})[0]||null;
  return {fut:dated.filter(function(x){return x.diff>=1;}).slice(0,3),now:cur};
}
function reasonText(job){
  const raw=job&&job.error;
  const m=String((raw&&raw.message)||raw||'');
  if(m.indexOf('wx:')===0){
    const c=m.slice(3);
    if(c==='permission_denied')return '没有获取天气数据的权限（permission_denied）';
    if(c==='no_data')return '天气服务返回了空数据';
    return '服务返回错误：'+c;
  }
  return m?'错误：'+m.slice(0,80):'原因未知';
}

function mount(ctx){
  const {root,el,state,ui,update,host,size,day,runAsync}=ctx;
  const SOURCE='official.weather.forecast';
  const today=day();
  const job=(ui.jobs&&ui.jobs.weather)||null;
  const failed=!!job&&job.status==='error';
  const loading=!failed&&!(job&&job.status==='ok');
  const snap=ui.snap||(state&&state.snap)||null;
  const big=size!=='3x3';
  const tall=size==='3x6'||size==='6x6';
  const h=function(tag,cls,...rest){
    return el(tag,cls?{class:cls}:{},...rest.filter(function(k){return k!=null&&k!==false;}));
  };

  async function loadWeather(){
    const r=await host.fetchData(SOURCE);
    if(!r||r.status!=='ok')throw new Error('wx:'+((r&&(r.errorCode||r.status))||'empty'));
    const d=r.data;
    const fc=d&&Array.isArray(d.forecast)?d.forecast:[];
    if(!d||typeof d!=='object'||Array.isArray(d)||(d.temperature==null&&!d.weather&&!fc.length)){
      throw new Error('wx:no_data');
    }
    const data={
      temperature:d.temperature,weather:d.weather,wind_power:d.wind_power,
      wind_direction:d.wind_direction,report_time:d.report_time,
      forecast:fc.slice(0,7).filter(function(f){return f&&typeof f==='object';}).map(function(f){
        return {date:f.date,temp_min:f.temp_min,temp_max:f.temp_max,weather_day:f.weather_day};
      })
    };
    const next={data:data,stale:!!r.isStale,at:Date.now()};
    ui.snap=next;
    try{await update(function(s){return Object.assign({},s||{},{snap:next});});}catch(e){}
    return true;
  }
  function reload(){
    if(job&&job.status==='loading')return;
    if(ui.jobs)delete ui.jobs.weather;
    runAsync('weather',loadWeather);
  }

  function nowBlock(d,cur){
    const meta=h('div','wx-meta',
      el('div',{class:'wx-cond',title:d.weather?String(d.weather):''},d.weather?String(d.weather):'天气未提供'),
      h('div','wx-wind',windIcon(),h('span','',fmtWind(d.wind_direction,d.wind_power))),
      (tall&&cur)?h('div','wx-today','今日 '+fmtT(cur.f.temp_min)+' ~ '+fmtT(cur.f.temp_max)):null
    );
    return h('section','wx-now',
      h('div','wx-icon',wxIcon(kindOf(d.weather))),
      el('div',{class:'wx-temp','aria-label':'当前温度'},fmtT(d.temperature)),
      meta);
  }
  function daysBlock(fut){
    if(!fut.length){
      return h('section','wx-days is-empty',h('div','wx-note','没有可用的未来三天预报'));
    }
    const sec=el('section',{class:'wx-days','aria-label':'未来三天预报'});
    fut.forEach(function(x){
      const f=x.f,lab=dayLabel(f.date,x.diff);
      const txt=f.weather_day?String(f.weather_day):'未提供';
      sec.appendChild(h('article','wx-day',
        h('div','wx-dl',h('b','',lab.main),h('span','',lab.sub)),
        h('div','wx-di',wxIcon(kindOf(f.weather_day))),
        el('div',{class:'wx-dw',title:txt},txt),
        h('div','wx-dt',fmtT(f.temp_min)+' ~ '+fmtT(f.temp_max))));
    });
    if(fut.length<3)sec.appendChild(h('div','wx-note','服务只返回了 '+fut.length+' 天预报'));
    return sec;
  }

  function errorBlock(){
    return h('div','wx-empty',
      h('div','wx-empty-t','暂时获取不到杭州天气'),
      h('div','wx-empty-d',reasonText(job)),
      h('div','wx-empty-d','目前没有可显示的数据，也没有更新时间。'),
      el('button',{type:'button',class:'wx-btn',onclick:reload},'重试'));
  }
  function skeleton(){
    return h('div','wx-skel',h('div','wx-bar'),h('div','wx-bar short'),h('div','wx-skel-t','正在获取杭州天气…'));
  }
  function footBlock(){
    const kids=[];
    if(snap){
      const d=snap.data||{};
      const t=fmtReport(d.report_time);
      let line=t?'数据更新 '+t:'数据未提供更新时间';
      if(snap.stale)line+=' · 可能已过期';
      kids.push(el('div',{class:'wx-upd',title:d.report_time!=null?String(d.report_time):''},line));
      if(failed){
        kids.push(h('div','wx-st is-bad','刷新失败，仍为上次数据',big?h('span','wx-reason','（'+reasonText(job)+'）'):null));
      }else if(loading){
        kids.push(h('div','wx-st','正在刷新…'));
      }else{
        const at=fmtAt(snap.at,today);
        kids.push(h('div','wx-st',at?'获取于 '+at:''));
      }
    }else if(failed){
      kids.push(h('div','wx-upd','没有更新时间（尚未成功获取）'));
    }else{
      kids.push(h('div','wx-upd','正在获取，暂无更新时间'));
    }
    return el('div',{class:'wx-foot',role:'status'},...kids);
  }

  const refreshBtn=el('button',{
    type:'button',class:'wx-refresh'+(loading?' is-loading':'')+(failed?' is-bad':''),
    'aria-label':'刷新杭州天气',title:'刷新',disabled:loading&&!!job,onclick:reload
  },refreshIcon());
  const bodyKids=[];
  if(snap){
    const d=snap.data||{};
    const ds=listDays(Array.isArray(d.forecast)?d.forecast:[],today);
    bodyKids.push(nowBlock(d,ds.now));
    if(big)bodyKids.push(daysBlock(ds.fut));
  }else if(failed){
    bodyKids.push(errorBlock());
  }else{
    bodyKids.push(skeleton());
  }
  root.appendChild(h('div','wx',
    h('div','wx-head',h('div','wx-city','杭州'),refreshBtn),
    el('div',{class:'wx-body'},...bodyKids),
    footBlock()));

  if(!job){
    Promise.resolve().then(function(){
      if(!(ui.jobs&&ui.jobs.weather))runAsync('weather',loadWeather);
    });
  }
